resource autoscale 'Microsoft.Insights/autoscaleSettings@2022-10-01' = {
  name: 'autoscale-quotient-prod'
  location: location
  properties: {
    enabled: true
    targetResourceUri: appServicePlan.id
    profiles: [
      {
        name: 'business-hours'
        capacity: { minimum: '4', maximum: '20', default: '6' }
        rules: [
          {
            // Leading indicator: scale out on request volume
            metricTrigger: {
              metricName: 'Requests'
              metricResourceUri: appServicePlan.id
              timeGrain: 'PT1M'
              statistic: 'Total'
              timeWindow: 'PT5M'
              timeAggregation: 'Average'
              operator: 'GreaterThan'
              threshold: 9000
            }
            scaleAction: { direction: 'Increase', type: 'ChangeCount', value: '2', cooldown: 'PT5M' }
          }
          {
            metricTrigger: {
              metricName: 'Requests'
              metricResourceUri: appServicePlan.id
              timeGrain: 'PT1M'
              statistic: 'Total'
              timeWindow: 'PT15M'
              timeAggregation: 'Average'
              operator: 'LessThan'
              threshold: 2000
            }
            // Longer cooldown so we do not scale in during a lull
            scaleAction: { direction: 'Decrease', type: 'ChangeCount', value: '1', cooldown: 'PT20M' }
          }
        ]
      }
    ]
  }
}
